import {NARUTO_V2_META as META} from './naruto-v2-meta.js';
import {narutoV2Pose} from '../characters/naruto_v2.js';
import {personalCaster} from '../engine/personal-ultimate.js';
import {cinematicSteps} from '../engine/ultimate-rules.js';
export function narutoV2Sprite(ctx,images,key,row,col,x,y,scale=1,angle=0,face=1){const m=META[key],im=images[key];if(!m||!im?.complete||!im.naturalWidth)return;row=Math.max(0,Math.min(m.rows-1,row));col=Math.max(0,Math.min(m.rowCounts[row]-1,col));const [w,h]=m.frameSize,[px,py]=m.pivot;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale*(face<0?-1:1),scale);ctx.drawImage(im,col*w,row*h,w,h,-px,-py,w,h);ctx.restore();}
export function drawNarutoV2Actor(ctx,images,d,f,hurt=false,override=null){if(f.state==='v2rasengan'&&f.v2Blink&&f.age<.1&&f.introAge==null&&!d.narutoV2Transform)return;let p=narutoV2Pose(f,hurt);const trans=d.narutoV2Transform,c=personalCaster(d,f);
 if(f.introAge!=null){const n=Math.min(7,Math.floor(f.introAge/2.5*8));p={key:'naruto_v2_intro',row:Math.floor(n/4),frame:n%4};}
 else if(trans?.ownerUid===f.uid){const n=Math.min(7,Math.floor(trans.elapsed/cinematicSteps(trans)*8));p={key:'naruto_v2_transform',row:Math.floor(n/4),frame:n%4};}
 else if(c||override){const u=d.personalUltimate?.cinematic||d.teamUltimate?.cinematic,a=d.personalUltimate?.attack;p={key:'naruto_v2_ultimate_actor',row:f.baryon?1:0,frame:u?Math.min(3,Math.floor(u.elapsed/cinematicSteps(u)*4)):a?.phase==='travel'?2:3};}
 if(f.state==='defeat')p={key:f.baryon?'naruto_v2_baryon':'naruto_v2',row:7,frame:Math.min(3,Math.floor((d.tick-(f.deathTick??d.tick))/7))};
 narutoV2Sprite(ctx,images,p.key,p.row,p.frame,f.x,f.y,.86,0,f.face);
}
export function drawNarutoV2Back(ctx,images,d,clock=0){for(const f of d.fighters)if(f.id==='naruto_v2'&&f.hp>0){const trans=d.narutoV2Transform;if(f.introAge!=null){const n=Math.min(7,Math.floor(f.introAge/2.5*8));ctx.save();ctx.globalAlpha=.38;narutoV2Sprite(ctx,images,'naruto_v2_intro_vfx',Math.floor(n/4),n%4,f.x,f.y-38,.46);ctx.restore();}else if(trans?.ownerUid===f.uid){ctx.save();ctx.globalAlpha=.65;narutoV2Sprite(ctx,images,'naruto_v2_transform_vfx',0,Math.min(3,Math.floor(trans.elapsed/cinematicSteps(trans)*4)),f.x,f.y-45,.55);ctx.restore();}}}
export function drawNarutoV2World(ctx,images,d,clock=0){const a=d.personalUltimate?.attack;if(a?.kind==='kuramarasengan'){if(a.phase==='warning'){ctx.save();ctx.strokeStyle='#75d9ff';ctx.lineWidth=3;ctx.setLineDash([10,8]);ctx.beginPath();ctx.ellipse(a.targetX,a.targetY,165,90,0,0,Math.PI*2);ctx.stroke();ctx.restore();}else narutoV2Sprite(ctx,images,'naruto_v2_ultimate_vfx',0,Math.min(3,Math.floor((d.tick-a.launch)/10)),a.targetX,a.targetY-45,.65);}
 if(a?.kind==='finalimpact'){const f=d.fighters.find(f=>f.uid===a.ownerUid);if(a.phase==='warning'){ctx.save();ctx.strokeStyle='#ff7256';ctx.lineWidth=2;ctx.setLineDash([10,8]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(a.x+a.dx*576,a.y+a.dy*576);ctx.stroke();ctx.restore();}else if(f)narutoV2Sprite(ctx,images,'naruto_v2_ultimate_vfx',1,Math.min(3,Math.floor((d.tick-a.launch)/10)),f.x,f.y-40,.7,Math.atan2(a.dy,a.dx));}
 for(const f of d.fighters)if(f.id==='naruto_v2'&&f.hp>0&&d.tick<f.tailGuardUntil){ctx.save();ctx.globalAlpha=.6;narutoV2Sprite(ctx,images,'naruto_v2_baryon_vfx',1,Math.floor(clock*8)%4,f.x+f.face*25,f.y-45,.38,0,f.face);ctx.restore();}}
export function drawNarutoV2Shot(ctx,images,s,x,y,clock){narutoV2Sprite(ctx,images,s.form==='baryon'?'naruto_v2_baryon_vfx':'naruto_v2_vfx',2,Math.floor(clock*10)%3,x,y,.32,Math.atan2(s.vy,s.vx));}
export function drawNarutoV2Burst(ctx,images,b){const p=1-b.life/b.max,red=b.form==='baryon';narutoV2Sprite(ctx,images,b.ultimate?'naruto_v2_ultimate_vfx':red?'naruto_v2_baryon_vfx':'naruto_v2_vfx',b.ultimate?(red?1:0):b.action==='clone'?1:b.action==='counter'?1:0,Math.min(3,Math.floor(p*4)),b.x,b.y,b.ultimate?.7:.37);}
export function drawNarutoV2Chat(ctx,images,c,line=null,reduced=false,baryon=false){const p=c.elapsed/cinematicSteps(c),row=baryon?1:0,col=1,m=META.naruto_v2_dialogue,b=m.bounds[row][col],w=b[2]-b[0],h=b[3]-b[1],scale=Math.min(760/w,180/h),cx=(b[0]+b[2])/2,cy=(b[1]+b[3])/2;ctx.save();ctx.globalAlpha=Math.max(0,Math.min(1,p*10,(1-p)*12));narutoV2Sprite(ctx,images,'naruto_v2_dialogue',row,col,480-(cx-m.pivot[0])*scale,438-(cy-m.pivot[1])*scale,scale);const x=480+w*scale*.16;ctx.fillStyle='#fff0d3';ctx.textAlign='center';ctx.font='bold 14px Georgia';ctx.fillText(baryon?'NARUTO · BARYON MODE':'NARUTO · KURAMA LINK MODE',x,410,w*scale*.52);ctx.font='bold 19px Georgia';ctx.fillText(line||(baryon?'This is the end!':'Kurama! Giant Rasengan!'),x,449,w*scale*.52);ctx.restore();}
export function drawNarutoV2Cinematic(ctx,images,d,reduced=false){const c=d.narutoV2Transform||d.personalUltimate?.cinematic;if(c&&['narutotransform','kuramarasengan','finalimpact'].includes(c.kind))drawNarutoV2Chat(ctx,images,c,c.kind==='narutotransform'?'Baryon Mode!':null,reduced,c.kind!=='kuramarasengan');}
